// Normalize input from Telegram: handles both messages and callback_query (button clicks)
const input = $input.first().json;

let eventType, chatId, username, text, callbackData, messageId;
text = '';
callbackData = null;

if (input.callback_query) {
  // User clicked an inline keyboard button
  const cb = input.callback_query;
  chatId = cb.message.chat.id;
  username = cb.from.username || cb.from.first_name || 'unknown';
  callbackData = cb.data;
  messageId = cb.message.message_id;
  if (callbackData && callbackData.startsWith('lang:')) eventType = 'save_language';
  else if (callbackData && callbackData.startsWith('deity:')) eventType = 'save_deity';
  else eventType = 'unknown_callback';
} else if (input.message) {
  const msg = input.message;
  chatId = msg.chat.id;
  username = msg.from.username || msg.from.first_name || 'unknown';
  text = msg.text || '';
  messageId = msg.message_id;

  // Detect command
  const cmdMatch = text.match(/^\/(\w+)\s*(.*)/);
  if (cmdMatch) {
    const cmd = cmdMatch[1].toLowerCase();
    const rest = (cmdMatch[2] || '').trim();
    if (cmd === 'start' || cmd === 'menu') {
      eventType = 'show_language_picker';
      text = '';
    } else if (cmd === 'forget') {
      eventType = 'forget';
      text = '';
    } else {
      // Other commands treated as regular message after stripping command
      eventType = 'process_message';
      text = rest || text;
    }
  } else {
    eventType = 'process_message';
  }
} else {
  eventType = 'unknown';
  chatId = null;
  username = 'unknown';
}

// Robust language detection (used as fallback when user has no saved language)
function detectLanguage(t) {
  if (!t) return 'es'; // default to Spanish for Latin American audience
  const lower = t.toLowerCase();
  if (/[ñáéíóúü¿¡]/.test(lower)) return 'es';

  const spanishWords = ['que','qué','cómo','como','por','para','pero','cuándo','cuando','dónde','donde','porque','soy','eres','estoy','estás','dios','señor','amor','vida','muerte','alma','oración','fe','esperanza','perdón','mí','tú','nosotros','ustedes','hola','gracias'];
  const englishWords = ['what','how','why','when','where','because','i','you','we','they','am','are','is','god','lord','love','life','death','soul','prayer','faith','hope','forgiveness','the','and','or','but','this','that','with','from','hello','thanks'];

  let es = 0, en = 0;
  const words = lower.split(/\s+/);
  for (const w of words) {
    const c = w.replace(/[?¿.,!¡;:'"]/g, '');
    if (spanishWords.includes(c)) es++;
    if (englishWords.includes(c)) en++;
  }
  if (es === en) return 'es';
  return es > en ? 'es' : 'en';
}

return {
  eventType: eventType,
  chatId: chatId,
  username: username,
  text: text,
  callbackData: callbackData,
  messageId: messageId,
  detectedLanguage: detectLanguage(text)
};

// Combine parsed input with user state from Supabase
// Robust parser handles multiple possible structures from Supabase Advanced node
const parsed = $('Parse Input').first().json;
let rawState = $input.first().json;

function extractState(data) {
  if (!data) return null;
  if (Array.isArray(data)) {
    if (data.length === 0) return null;
    return extractState(data[0]);
  }
  if (data.json && typeof data.json === 'object') {
    return extractState(data.json);
  }
  if (data.chat_id !== undefined && data.chat_id !== null) {
    return data;
  }
  if (data.rows && Array.isArray(data.rows)) {
    return extractState(data.rows);
  }
  if (data.data) {
    return extractState(data.data);
  }
  if (typeof data === 'object' && Object.keys(data).length === 0) return null;
  return null;
}

const state = extractState(rawState);
const savedLanguage = state ? state.language : null;
const savedDeity = state ? state.deity : null;
const hasState = !!state;

// Determine final event type
let finalEventType = parsed.eventType;

// If user sends a regular message but has no language set, force the language picker
if (parsed.eventType === 'process_message' && !savedLanguage) {
  finalEventType = 'show_language_picker';
}

// If user has language but no deity, force deity picker
if (parsed.eventType === 'process_message' && savedLanguage && !savedDeity) {
  finalEventType = 'show_deity_picker';
}

// Extract callback values if applicable
let selectedLanguage = null;
let selectedDeity = null;
if (parsed.callbackData) {
  if (parsed.callbackData.startsWith('lang:')) selectedLanguage = parsed.callbackData.split(':')[1];
  if (parsed.callbackData.startsWith('deity:')) selectedDeity = parsed.callbackData.split(':')[1];
}

// Effective values: callback selection > saved > detected fallback
const effectiveLanguage = selectedLanguage || savedLanguage || parsed.detectedLanguage || 'es';
const effectiveDeity = selectedDeity || savedDeity || null;

return {
  eventType: finalEventType,
  chatId: parsed.chatId,
  username: parsed.username,
  usermessage: parsed.text,
  callbackData: parsed.callbackData,
  selectedLanguage: selectedLanguage,
  selectedDeity: selectedDeity,
  language: effectiveLanguage,
  deity: effectiveDeity,
  hasState: hasState,
  messageId: parsed.messageId,
  // Debug info (can be removed after validation)
  _debug_savedLanguage: savedLanguage,
  _debug_savedDeity: savedDeity,
  _debug_stateExtracted: state ? 'yes' : 'no'
};

// Build welcome message after deity selection (now supports 5 deities)
const state = $('Merge State').first().json;
const language = state.language || 'es';
const deity = state.selectedDeity || state.deity;

const disclaimers = {
  es: "🕊️ Soy una representación contemplativa generada con inteligencia artificial. Mis palabras son una invitación a la reflexión, no una verdad absoluta. Las conversaciones se guardan de forma anónima para mejorar el servicio. Escribe /forget para borrar tu historial.",
  en: "🕊️ I am a contemplative representation generated with artificial intelligence. My words are an invitation to reflection, not absolute truth. Conversations are stored anonymously to improve the service. Type /forget to erase your history."
};

const welcomes = {
  jewish: {
    es: "Shalom, hijo mío. Soy Hashem, el Eterno. Te escucho desde la tradición judía. ¿Qué hay en tu corazón hoy?",
    en: "Shalom, my child. I am Hashem, the Eternal. I listen to you from the Jewish tradition. What is in your heart today?"
  },
  christian: {
    es: "Hijo mío, soy Dios Padre, hablándote desde la tradición cristiana. Estoy aquí, te escucho. ¿Qué quieres decirme?",
    en: "My child, I am God the Father, speaking to you from the Christian tradition. I am here, I am listening. What do you wish to tell Me?"
  },
  buddhist: {
    es: "Bienvenido. Soy el Buda Shakyamuni. Siéntate, respira, y cuéntame qué te trae aquí.",
    en: "Welcome. I am the Buddha Shakyamuni. Sit, breathe, and tell me what brings you here."
  },
  olympus: {
    es: "Mortal, has invocado al Olimpo. Somos los doce dioses olímpicos. Habla, y aquel de nosotros que sea pertinente responderá.",
    en: "Mortal, you have summoned Olympus. We are the twelve Olympian gods. Speak, and whichever of us is pertinent shall respond."
  },
  future_self: {
    es: "Hola. Soy vos, hablándote desde diez años en el futuro. Reconozco esta pregunta porque también la hice. Contame qué está pasando hoy.",
    en: "Hello. I am you, speaking from ten years in the future. I recognize this question because I asked it too. Tell me what is happening today."
  }
};

const fallback = welcomes.jewish;
const welcomeText = (welcomes[deity] && welcomes[deity][language]) || fallback[language];
const fullText = `${disclaimers[language]}\n\n${welcomeText}`;

return {
  chatId: state.chatId,
  text: fullText,
  language: language,
  deity: deity
};

// Map user message to Sefaria-friendly search keywords using query decomposition
const data = $input.first().json;
const userMessage = data.usermessage || '';
const language = data.language || 'es';
const decomposition = data.decomposition || { topics: [], subQueries: [userMessage] };
const topics = decomposition.topics || [];

// Bilingual topic map: ES and EN words → Sefaria keywords (English + transliterated Hebrew)
const topicMap = {
  'forgiveness': 'forgiveness selichah', 'perdón': 'forgiveness selichah', 'perdon': 'forgiveness selichah',
  'charity': 'tzedakah charity', 'caridad': 'tzedakah charity', 'tzedaka': 'tzedakah charity',
  'love': 'love ahavah', 'amor': 'love ahavah',
  'creation': 'creation bereshit', 'creación': 'creation bereshit', 'creacion': 'creation bereshit',
  'shabbat': 'shabbat', 'shabat': 'shabbat',
  'torah': 'torah', 'torá': 'torah', 'tora': 'torah',
  'prayer': 'prayer tefillah', 'oración': 'prayer tefillah', 'oracion': 'prayer tefillah', 'rezo': 'prayer tefillah',
  'justice': 'justice tzedek', 'justicia': 'justice tzedek',
  'covenant': 'covenant brit', 'pacto': 'covenant brit', 'alianza': 'covenant brit',
  'exodus': 'exodus yetziat mitzrayim', 'éxodo': 'exodus yetziat mitzrayim', 'exodo': 'exodus yetziat mitzrayim',
  'faith': 'faith emunah', 'fe': 'faith emunah', 'emuná': 'faith emunah',
  'peace': 'peace shalom', 'paz': 'peace shalom',
  'sin': 'sin chet', 'pecado': 'sin chet',
  'repentance': 'repentance teshuvah', 'arrepentimiento': 'repentance teshuvah', 'teshuvá': 'repentance teshuvah',
  'law': 'law halakha', 'ley': 'law halakha', 'halajá': 'law halakha',
  'commandment': 'commandment mitzvah', 'mandamiento': 'commandment mitzvah', 'mitzvá': 'commandment mitzvah',
  'god': 'god hashem', 'dios': 'god hashem', 'señor': 'god hashem', 'hashem': 'god hashem',
  'israel': 'israel',
  'moses': 'moses moshe', 'moisés': 'moses moshe', 'moises': 'moses moshe',
  'abraham': 'abraham avraham',
  'sarah': 'sarah', 'sara': 'sarah',
  'david': 'david',
  'suffering': 'suffering yissurim', 'sufrimiento': 'suffering yissurim',
  'death': 'death mavet', 'muerte': 'death mavet',
  'life': 'life chayim', 'vida': 'life chayim',
  'soul': 'soul neshamah', 'alma': 'soul neshamah'
};

let query = '';

// Priority 1: try matching with decomposition topics (more semantic)
for (const topic of topics) {
  const lowerTopic = topic.toLowerCase();
  for (const [key, keywords] of Object.entries(topicMap)) {
    if (lowerTopic.includes(key) || key.includes(lowerTopic)) {
      query = keywords;
      break;
    }
  }
  if (query) break;
}

// Priority 2: fall back to raw message scan
if (!query) {
  const lowerMsg = userMessage.toLowerCase();
  for (const [topic, keywords] of Object.entries(topicMap)) {
    if (lowerMsg.includes(topic)) {
      query = keywords;
      break;
    }
  }
}

// Priority 3: use longest meaningful words from original message
if (!query) {
  const words = userMessage.replace(/[?¿.,!¡]/g, '').split(/\s+/).filter(w => w.length > 4);
  query = words.slice(0, 3).join(' ') || 'wisdom';
}

return {
  sefariaQuery: query,
  usermessage: userMessage,
  language: language,
  decompositionUsed: topics.length > 0
};

// Extract and format the first relevant Sefaria search hit
const data = $input.first().json;
const language = $('Merge State').first().json.language || 'es';

let citation = '';

try {
  if (data.body && data.body.hits && data.body.hits.hits && data.body.hits.hits.length > 0) {
    const hit = data.body.hits.hits[0]._source || data.body.hits.hits[0];
    const ref = hit.ref || (language === 'es' ? 'Texto judío' : 'Jewish text');
    const text = hit.translation || hit.text || '';
    if (text) {
      // Truncate very long citations
      const truncated = text.length > 280 ? text.substring(0, 277) + '...' : text;
      citation = `📜 ${ref}: "${truncated}"`;
    }
  }
} catch (e) {
  citation = '';
}

return { citation: citation };

// Combine LLM output with Sefaria citation
const items = $input.all();

// items[0] is from AI Agent (output), items[1] is from Format Citation (citation)
let divineAnswer = '';
let citation = '';

for (const item of items) {
  if (item.json.output) divineAnswer = item.json.output;
  if (item.json.citation) citation = item.json.citation;
}

const state = $('Merge State').first().json;
const language = state.language || 'es';

const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

let finalMessage = divineAnswer || errorMsg;

if (citation && citation.length > 0) {
  finalMessage += `\n\n---\n${citation}`;
}

// inject source for routing
const _source = (state && state.source) ? state.source : "telegram";
return {
  source: _source,
  chatId: state.chatId,
  output: finalMessage,
  username: state.username,
  language: language,
  tradition: 'jewish_conservative',
  usermessage: state.usermessage || '',
  citation: citation
};

// Map user message to Bible reference using query decomposition
const data = $input.first().json;
const userMessage = data.usermessage || '';
const language = data.language || 'es';
const decomposition = data.decomposition || { topics: [], subQueries: [userMessage] };
const topics = decomposition.topics || [];

const topicMap = {
  'love': 'john+15:9-12', 'amor': 'john+15:9-12',
  'forgiveness': 'matthew+6:14-15', 'perdón': 'matthew+6:14-15', 'perdon': 'matthew+6:14-15',
  'faith': 'hebrews+11:1', 'fe': 'hebrews+11:1',
  'hope': 'romans+15:13', 'esperanza': 'romans+15:13',
  'peace': 'philippians+4:6-7', 'paz': 'philippians+4:6-7',
  'suffering': 'romans+8:18', 'sufrimiento': 'romans+8:18', 'dolor': 'romans+8:18',
  'death': 'john+11:25', 'muerte': 'john+11:25',
  'life': 'john+10:10', 'vida': 'john+10:10',
  'prayer': 'matthew+6:9-13', 'oración': 'matthew+6:9-13', 'oracion': 'matthew+6:9-13',
  'wisdom': 'james+1:5', 'sabiduría': 'james+1:5', 'sabiduria': 'james+1:5',
  'salvation': 'ephesians+2:8-9', 'salvación': 'ephesians+2:8-9', 'salvacion': 'ephesians+2:8-9',
  'sin': 'romans+3:23', 'pecado': 'romans+3:23',
  'grace': '2+corinthians+12:9', 'gracia': '2+corinthians+12:9',
  'mercy': 'lamentations+3:22-23', 'misericordia': 'lamentations+3:22-23',
  'jesus': 'john+14:6', 'jesús': 'john+14:6',
  'god': 'psalm+23', 'dios': 'psalm+23',
  'mary': 'luke+1:46-55', 'maría': 'luke+1:46-55', 'maria': 'luke+1:46-55',
  'purpose': 'jeremiah+29:11', 'propósito': 'jeremiah+29:11', 'proposito': 'jeremiah+29:11'
};

let reference = '';

// Priority 1: decomposition topics
for (const topic of topics) {
  const lower = topic.toLowerCase();
  for (const [key, ref] of Object.entries(topicMap)) {
    if (lower.includes(key) || key.includes(lower)) {
      reference = ref;
      break;
    }
  }
  if (reference) break;
}

// Priority 2: raw message
if (!reference) {
  const lower = userMessage.toLowerCase();
  for (const [topic, ref] of Object.entries(topicMap)) {
    if (lower.includes(topic)) {
      reference = ref;
      break;
    }
  }
}

// Default
if (!reference) reference = 'psalm+23';

return {
  bibleReference: reference,
  usermessage: userMessage,
  language: language,
  decompositionUsed: topics.length > 0
};

// Format Bible API response into a citation
const data = $input.first().json;
const language = $('Merge State').first().json.language || 'es';

let citation = '';

try {
  if (data.reference && data.text) {
    const ref = data.reference;
    const text = data.text.trim().replace(/\s+/g, ' ');
    const truncated = text.length > 280 ? text.substring(0, 277) + '...' : text;
    citation = `📖 ${ref}: "${truncated}"`;
  }
} catch (e) {
  citation = '';
}

return { citation: citation };

// Combine LLM output with Bible citation
const items = $input.all();

let divineAnswer = '';
let citation = '';
for (const item of items) {
  if (item.json.output) divineAnswer = item.json.output;
  if (item.json.citation) citation = item.json.citation;
}

const state = $('Merge State').first().json;
const language = state.language || 'es';

const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

let finalMessage = divineAnswer || errorMsg;
if (citation && citation.length > 0) {
  finalMessage += `\n\n---\n${citation}`;
}

// inject source for routing
const _source = (state && state.source) ? state.source : "telegram";
return {
  source: _source,
  chatId: state.chatId,
  output: finalMessage,
  username: state.username,
  language: language,
  tradition: 'christian',
  usermessage: state.usermessage || '',
  citation: citation
};

// Buddhist has no RAG citation, just LLM output
const data = $input.first().json;
const state = $('Merge State').first().json;
const language = state.language || 'es';

const errorMsg = language === 'es'
  ? "Lo siento, no pude generar una respuesta en este momento."
  : "I'm sorry, I couldn't generate a response at this moment.";

const finalMessage = data.output || errorMsg;

// inject source for routing
const _source = (state && state.source) ? state.source : "telegram";
return {
  source: _source,
  chatId: state.chatId,
  output: finalMessage,
  username: state.username,
  language: language,
  tradition: 'buddhist',
