// Olympus has no RAG citation, just LLM output
const data = $input.first().json;
const state = $('Merge State').first().json;
const language = state.language || 'es';

const errorMsg = language === 'es'
  ? "Los Olímpicos guardan silencio en este momento."
  : "The Olympians keep silence at this moment.";

const finalMessage = data.output || errorMsg;

// inject source for routing
const _source = (state && state.source) ? state.source : "telegram";
return {
  source: _source,
  chatId: state.chatId,
  output: finalMessage,
  username: state.username,
  language: language,
  tradition: 'olympus',
  usermessage: state.usermessage || '',
  citation: ''
};

// Future Self has no RAG citation, just LLM output
const data = $input.first().json;
const state = $('Merge State').first().json;
const language = state.language || 'es';

const errorMsg = language === 'es'
  ? "No tengo nada que decirte en este momento. Volvé en un rato."
  : "I have nothing to tell you right now. Come back in a while.";

const finalMessage = data.output || errorMsg;

// inject source for routing
const _source = (state && state.source) ? state.source : "telegram";
return {
  source: _source,
  chatId: state.chatId,
  output: finalMessage,
  username: state.username,
  language: language,
  tradition: 'future_self',
  usermessage: state.usermessage || '',
  citation: ''
};

// Parse the JSON output from Query Decomposer and merge with state
const decompOutput = $input.first().json.output || '{}';
const webState = $('Web Normalize State').first();
const tgState = $('Merge State').first();
const state = (webState ? webState.json : null) || (tgState ? tgState.json : null);
if (!state) throw new Error('Missing Web Normalize State (web) or Merge State (telegram)');

let decomposition = {
  intent: state.usermessage,
  subQueries: [state.usermessage],
  topics: [],
  isExistential: true
};

try {
  // Extract JSON (LLM sometimes wraps in markdown code blocks)
  let jsonText = decompOutput;
  const jsonMatch = decompOutput.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  if (jsonMatch) {
    jsonText = jsonMatch[1];
  } else {
    // Try to find raw JSON
    const firstBrace = decompOutput.indexOf('{');
    const lastBrace = decompOutput.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace > firstBrace) {
      jsonText = decompOutput.substring(firstBrace, lastBrace + 1);
    }
  }

  const parsed = JSON.parse(jsonText);
  decomposition = {
    intent: parsed.intent || state.usermessage,
    subQueries: Array.isArray(parsed.subQueries) && parsed.subQueries.length > 0
      ? parsed.subQueries 
      : [state.usermessage],
    topics: Array.isArray(parsed.topics) ? parsed.topics : [],
    isExistential: parsed.isExistential !== undefined ? parsed.isExistential : true
  };
} catch (e) {
  // Fallback: use original message
  console.log('Decomposition parsing failed, using fallback:', e.message);
}

// Return enriched state (everything from Merge State + decomposition data)
return {
  ...state,
  decomposition: decomposition,
  // For convenience downstream, expose the "best" query to use for retrieval
  bestQuery: decomposition.subQueries[0],
  enrichedContext: `Intent: ${decomposition.intent}\nKey topics: ${decomposition.topics.join(', ')}\nSub-queries explored: ${decomposition.subQueries.join('; ')}`
};

// Build LangFuse trace payload
// This runs after Log Conversation; sends trace asynchronously to LangFuse Cloud
const data = $input.first().json;

// Pick up the assembled response data from previous nodes
// Use a try-catch fallback since this depends on the deity branch
let response, usermessage, deity, language, chatId, username, citation;

try {
  // Try to find data from any of the assemble response nodes
  const assembleSources = [
    'Assemble Response',
    'Assemble Christian Response', 
    'Assemble Buddhist Response',
    'Assemble Olympus Response',
    'Assemble Future Self Response'
  ];

  let assembled = null;
  for (const src of assembleSources) {
    try {
      const node = $(src);
      if (node && node.first()) {
        assembled = node.first().json;
        break;
      }
    } catch (e) { continue; }
  }

  if (assembled) {
    response = assembled.output || '';
    usermessage = assembled.usermessage || '';
    deity = assembled.tradition || 'unknown';
    language = assembled.language || 'es';
    chatId = assembled.chatId || 0;
    username = assembled.username || 'anonymous';
    citation = assembled.citation || '';
  } else {
    response = data.output || '';
    usermessage = data.usermessage || '';
    deity = data.tradition || 'unknown';
    language = data.language || 'es';
    chatId = data.chatId || 0;
    username = 'anonymous';
    citation = '';
  }
} catch (e) {
  response = '';
  usermessage = '';
  deity = 'unknown';
  language = 'es';
  chatId = 0;
  username = 'anonymous';
  citation = '';
}

const now = new Date().toISOString();
const traceId = `${chatId}_${Date.now()}`;

// Build LangFuse ingestion payload
const payload = {
  batch: [
    {
      id: traceId,
      type: 'trace-create',
      timestamp: now,
      body: {
        id: traceId,
        timestamp: now,
        name: `god_is_typing_${deity}`,
        userId: String(chatId),
        sessionId: `${chatId}_${deity}`,
        input: usermessage,
        output: response,
        metadata: {
          deity: deity,
          language: language,
          hasCitation: citation.length > 0,
          source: 'telegram'
        },
        tags: [deity, language, 'production']
      }
    }
  ]
};

return { langfusePayload: payload, traceId: traceId };

// Rate Limit Evaluator
// Reads current state from Supabase, decides if user is allowed or blocked
// Rules:
//   - Max 3 questions per 24h window
//   - Window starts at the first question; resets 24h later
//   - If blocked, returns time remaining until reset

const decompState = $('Parse Decomposition').first().json;
const chatId = decompState.chatId;
const language = decompState.language || 'es';

// Get current state from Supabase (may be empty if first time)
let rateLimitState = $input.first().json;

// Normalize response (Supabase may wrap or array-wrap)
function extract(data) {
  if (!data) return null;
  if (Array.isArray(data)) {
    return data.length > 0 ? extract(data[0]) : null;
  }
  if (data.json && typeof data.json === 'object') return extract(data.json);
  if (data.chat_id !== undefined && data.chat_id !== null) return data;
  return null;
}

