  if (elapsed >= WINDOW_MS) {
    // Window expired, reset
    count = 0;
    windowStart = now;
    isNewWindow = true;
  } else if (count >= MAX_REQUESTS) {
    // Still within window AND limit exceeded
    blocked = true;
    const msLeft = WINDOW_MS - elapsed;
    const hoursLeft = Math.floor(msLeft / (60 * 60 * 1000));
    const minutesLeft = Math.floor((msLeft % (60 * 60 * 1000)) / (60 * 1000));
    timeRemaining = { hours: hoursLeft, minutes: minutesLeft, totalMs: msLeft };
